const hamburger = document.querySelector('#hamburger'); const navMenu = document.querySelector('#navMenu'); if (hamburger && navMenu) { hamburger.setAttribute('role', 'button'); hamburger.setAttribute('tabindex', '0'); hamburger.setAttribute('aria-controls', 'navMenu'); hamburger.setAttribute('aria-expanded', 'false'); const toggleMenu = () => { const isOpen = navMenu.classList.toggle('active'); hamburger.setAttribute('aria-expanded', String(isOpen)); }; hamburger.addEventListener('click', toggleMenu); hamburger.addEventListener('keydown', (event) => { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); toggleMenu(); } }); navMenu.querySelectorAll('a').forEach((link) => { link.addEventListener('click', () => { navMenu.classList.remove('active'); hamburger.setAttribute('aria-expanded', 'false'); }); }); } const counter = document.querySelector('#co2Counter'); if (counter && 'IntersectionObserver' in window) { const target = Number(counter.dataset.target || 0); const formatter = new Intl.NumberFormat('pt-BR'); let hasStarted = false; const animateCounter = () => { if (hasStarted) return; hasStarted = true; const duration = 1400; const startedAt = performance.now(); const frame = (now) => { const progress = Math.min((now - startedAt) / duration, 1); const eased = 1 - Math.pow(1 - progress, 3); counter.textContent = formatter.format(Math.round(target * eased)); if (progress < 1) window.requestAnimationFrame(frame); }; window.requestAnimationFrame(frame); }; const observer = new IntersectionObserver((entries) => { if (entries.some((entry) => entry.isIntersecting)) { animateCounter(); observer.disconnect(); } }, { threshold: 0.35 }); observer.observe(counter); } else if (counter) { counter.textContent = new Intl.NumberFormat('pt-BR').format(Number(counter.dataset.target || 0)); } if ('serviceWorker' in navigator) { window.addEventListener('load', () => { const serviceWorkerPath = document.body.classList.contains('policy-page') ? '../sw.js' : './sw.js'; navigator.serviceWorker.register(serviceWorkerPath).catch(() => undefined); }); }